Object.assign(window.CODELAB_OFFLINE_PACKS,{"topic-longestcommonsubsequence":{"key":"topic-longestcommonsubsequence","number":null,"title":"Longest Common Subsequence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Common Subsequence.py","code":"class Solution:\n    def longestCommonSubsequence(self, text1: str, text2: str) -> int:\n        dp = [[0] * (len(text2) + 1) for _ in range(len(text1) + 1)]\n        for i in range(1, len(text1) + 1):\n            for j in range(1, len(text2) + 1):\n                if text1[i - 1] == text2[j - 1]:\n                    dp[i][j] = 1 + dp[i - 1][j - 1]\n                else:\n                    dp[i][j] = max(dp[i - 1][j], dp[i][j - 1])\n        return dp[len(text1)][len(text2)]","hash":"492a0b1ea406bbf43b79b2704421ba616afca9e9fb2948606d249c574399a393","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Longest Common Subsequence.py"},{"source":"solutions","path":"Longest Common Subsequence.py"}]}],"sources":["solutions"]},"algorithm-longest-common-subsequence":{"key":"algorithm-longest-common-subsequence","number":null,"title":"longest common subsequence","difficulty":"Unknown","tags":["Algorithm Reference"],"documents":[],"sources":["algorithms"],"solutions":[{"language":"python","name":"longest_common_subsequence.py","code":"\"\"\"\nLCS Problem Statement: Given two sequences, find the length of longest subsequence\npresent in both of them.  A subsequence is a sequence that appears in the same relative\norder, but not necessarily continuous.\nExample:\"abc\", \"abg\" are subsequences of \"abcdefgh\".\n\"\"\"\n\n\ndef longest_common_subsequence(x: str, y: str):\n    \"\"\"\n    Finds the longest common subsequence between two strings. Also returns the\n    The subsequence found\n\n    Parameters\n    ----------\n\n    x: str, one of the strings\n    y: str, the other string\n\n    Returns\n    -------\n    L[m][n]: int, the length of the longest subsequence. Also equal to len(seq)\n    Seq: str, the subsequence found\n\n    >>> longest_common_subsequence(\"programming\", \"gaming\")\n    (6, 'gaming')\n    >>> longest_common_subsequence(\"physics\", \"smartphone\")\n    (2, 'ph')\n    >>> longest_common_subsequence(\"computer\", \"food\")\n    (1, 'o')\n    >>> longest_common_subsequence(\"\", \"abc\")  # One string is empty\n    (0, '')\n    >>> longest_common_subsequence(\"abc\", \"\")  # Other string is empty\n    (0, '')\n    >>> longest_common_subsequence(\"\", \"\")  # Both strings are empty\n    (0, '')\n    >>> longest_common_subsequence(\"abc\", \"def\")  # No common subsequence\n    (0, '')\n    >>> longest_common_subsequence(\"abc\", \"abc\")  # Identical strings\n    (3, 'abc')\n    >>> longest_common_subsequence(\"a\", \"a\")  # Single character match\n    (1, 'a')\n    >>> longest_common_subsequence(\"a\", \"b\")  # Single character no match\n    (0, '')\n    >>> longest_common_subsequence(\"abcdef\", \"ace\")  # Interleaved subsequence\n    (3, 'ace')\n    >>> longest_common_subsequence(\"ABCD\", \"ACBD\")  # No repeated characters\n    (3, 'ABD')\n    \"\"\"\n    # find the length of strings\n\n    assert x is not None\n    assert y is not None\n\n    m = len(x)\n    n = len(y)\n\n    # declaring the array for storing the dp values\n    dp = [[0] * (n + 1) for _ in range(m + 1)]\n\n    for i in range(1, m + 1):\n        for j in range(1, n + 1):\n            match = 1 if x[i - 1] == y[j - 1] else 0\n\n            dp[i][j] = max(dp[i - 1][j], dp[i][j - 1], dp[i - 1][j - 1] + match)\n\n    seq = \"\"\n    i, j = m, n\n    while i > 0 and j > 0:\n        match = 1 if x[i - 1] == y[j - 1] else 0\n\n        if dp[i][j] == dp[i - 1][j - 1] + match:\n            if match == 1:\n                seq = x[i - 1] + seq\n            i -= 1\n            j -= 1\n        elif dp[i][j] == dp[i - 1][j]:\n            i -= 1\n        else:\n            j -= 1\n\n    return dp[m][n], seq\n\n\nif __name__ == \"__main__\":\n    a = \"AGGTAB\"\n    b = \"GXTXAYB\"\n    expected_ln = 4\n    expected_subseq = \"GTAB\"\n\n    ln, subseq = longest_common_subsequence(a, b)\n    print(\"len =\", ln, \", sub-sequence =\", subseq)\n    import doctest\n\n    doctest.testmod()\n","hash":"f952d084db7594400192e2a00e12abe09dbc340a32220aacd54ff6c0895a75a4","origins":[{"source":"algorithms","path":"dynamic_programming/longest_common_subsequence.py","url":"https://github.com/TheAlgorithms/Python/blob/25c712f2692449e91a57748d328ef34fccf25654/dynamic_programming/longest_common_subsequence.py","commit":"25c712f2692449e91a57748d328ef34fccf25654"}]}]},"topic-longestcontinuousincreasingsubsequence":{"key":"topic-longestcontinuousincreasingsubsequence","number":null,"title":"Longest Continuous Increasing Subsequence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Continuous Increasing Subsequence.py","code":"class Solution:\n    def findLengthOfLCIS(self, nums: List[int]) -> int:\n        anchor, length = 0, 0\n        for i in range(len(nums)):\n            if i and nums[i - 1] >= nums[i]:\n                anchor = i\n            length = max(length, i - anchor + 1)\n        return length","hash":"ed1e6760760293f01bf3cc231b75974511db992a4906a991c8528d23e532c82f","origins":[{"source":"solutions","path":"Longest Continuous Increasing Subsequence.py"}]}],"sources":["solutions"]},"topic-longestcontinuoussubarraywithabsolutedifflessthanorequaltolimit":{"key":"topic-longestcontinuoussubarraywithabsolutedifflessthanorequaltolimit","number":null,"title":"Longest Continuous Subarray With Absolute Diff Less Than or Equal to Limit","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"java","name":"Longest Continuous Subarray With Absolute Diff Less Than or Equal to Limit.java","code":"class Solution {\n    public int longestSubarray(int[] nums, int limit) {\n        PriorityQueue<Integer> max = new PriorityQueue<>(Collections.reverseOrder());\n        PriorityQueue<Integer> min = new PriorityQueue<>();\n        int runningSize = 0;\n        int start = 0; \n        for(int end = 0; end < nums.length; end++){\n            max.add(nums[end]);\n            min.add(nums[end]);\n            int largest = max.peek();\n            int smallest = min.peek();\n            if (largest - smallest <= limit) {\n                runningSize = Math.max(runningSize, (end-start) + 1);\n            } else {\n                min.remove(new Integer(nums[start]));\n                max.remove(new Integer(nums[start]));\n                start++;\n            }\n        }\n        return runningSize;\n    }\n}","hash":"d7663056cd8f17bf5ad5f171c4a90d00a3733a200896c3085cc6a3bc39dc88e7","origins":[{"source":"solutions","path":"Mock Interviews/Google/Phone Interview 11/Longest Continuous Subarray With Absolute Diff Less Than or Equal to Limit.java"}]}],"sources":["solutions"]},"topic-longestcycleinagraph":{"key":"topic-longestcycleinagraph","number":null,"title":"Longest Cycle in a Graph","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Cycle in a Graph.py","code":"class Solution:\n    def longestCycle(self, edges: List[int]) -> int:\n        result, N = -1, len(edges)\n        visited = [False] * N\n        def dfs(node: int, distMap):\n            nonlocal result\n            visited[node] = True\n            neighbour = edges[node]\n            if neighbour != -1 and not visited[neighbour]:\n                distMap[neighbour] = distMap[node] + 1\n                dfs(neighbour, distMap)\n            elif neighbour != -1 and neighbour in distMap:\n                result = max(result, distMap[node] - distMap[neighbour] + 1)\n        for i in range(N):\n            if not visited[i]:\n                distMap = {i: 1}\n                dfs(i, distMap)\n        return result","hash":"814c88266301c83f335a4e1b903e60e5c49f7311824272367689bed7bec82e2f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-03 Leetcoding Challenge/Longest Cycle in a Graph.py"}]}],"sources":["solutions"]},"topic-longestduplicatesubstring":{"key":"topic-longestduplicatesubstring","number":null,"title":"Longest Duplicate Substring","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Duplicate Substring.py","code":"class Solution:\n    def longestDupSubstring(self, S: str) -> str:\n        base, n, modulus = 26, len(S), 2**32\n        nums = [ord(c) - ord('a') for c in S]\n        \n        def search(L):\n            h = 0\n            for i in range(L):\n                h = ((h * base) + nums[i]) % modulus\n            seen = {h}\n            baseL = pow(base, L, modulus)\n            for i in range(1, n - L + 1):\n                h = ((h * base) - (nums[i - 1] * baseL) + nums[i + L - 1]) % modulus\n                if h in seen:\n                    return i\n                seen.add(h)\n            return -1\n        \n        left, right = 1, n\n        while left <= right:\n            L = left + (right - left) // 2\n            if search(L) == -1:\n                right = L - 1\n            else:\n                left = L + 1\n        i = search(left - 1)\n        return S[i:i + left - 1]","hash":"9c4ee0aafb3c2e180684b402baf36648c04348f7c2faf88b9ca5282bcb33d320","origins":[{"source":"solutions","path":"Longest Duplicate Substring.py"}]}],"sources":["solutions"]},"topic-longestharmonioussubsequence":{"key":"topic-longestharmonioussubsequence","number":null,"title":"Longest Harmonious Subsequence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Harmonious Subsequence.py","code":"class Solution:\n    def findLHS(self, nums: List[int]) -> int:\n        result, hashMap = 0, defaultdict(int)\n        for num in nums:\n            hashMap[num] += 1\n            if num - 1 in hashMap:\n                result = max(result, hashMap[num] + hashMap[num - 1])\n            if num + 1 in hashMap:\n                result = max(result, hashMap[num] + hashMap[num + 1])\n        return result","hash":"627804e3d3b345b7f6c573f5445d12a68c8e7b7c5498a2cdd567e501cc1640b5","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Longest Harmonious Subsequence.py"}]}],"sources":["solutions"]},"topic-longestincreasingpathinamatrix":{"key":"topic-longestincreasingpathinamatrix","number":null,"title":"Longest Increasing Path in a Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Increasing Path in a Matrix.py","code":"class Solution:\n    def longestIncreasingPath(self, matrix: List[List[int]]) -> int:\n        numberOfRows = len(matrix)\n        result = 0\n        if numberOfRows == 0:\n            return result\n        numberOfColumns = len(matrix[0])\n        DIRECTIONS = [(0, 1), (1, 0), (0, -1), (-1, 0)]\n        resultCache = []\n        for _ in range(numberOfRows):\n            resultCache.append([0 for _ in range(numberOfColumns)])\n        \n        def dfs(matrix, row, column):\n            nonlocal numberOfRows, numberOfColumns, resultCache\n            if resultCache[row][column] != 0:\n                return resultCache[row][column]\n            for rowDirection, columnDirection in DIRECTIONS:\n                newRow, newColumn = row + rowDirection, column + columnDirection\n                if 0 <= newRow and newRow < numberOfRows and 0 <= newColumn and newColumn < numberOfColumns and matrix[newRow][newColumn] > matrix[row][column]:\n                    resultCache[row][column] = max(resultCache[row][column], dfs(matrix, newRow, newColumn))\n            resultCache[row][column] += 1\n            return resultCache[row][column]\n        \n        for row in range(numberOfRows):\n            for column in range(numberOfColumns):\n                result = max(result, dfs(matrix, row, column))\n        return result","hash":"2bd0a459d4fff0f8eeff217157c6b569634976f398e9e0ee6e72fa7e34aea747","origins":[{"source":"solutions","path":"Google Interview Questions/Longest Increasing Path in a Matrix.py"},{"source":"solutions","path":"LeetCoding Challenges/2021/2021-04 Leetcoding Challenge/Longest Increasing Path in a Matrix.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Longest Increasing Path in a Matrix.py"}]}],"sources":["solutions"]},"algorithm-longest-increasing-subsequence":{"key":"algorithm-longest-increasing-subsequence","number":null,"title":"longest increasing subsequence","difficulty":"Unknown","tags":["Algorithm Reference"],"documents":[],"sources":["algorithms"],"solutions":[{"language":"python","name":"longest_increasing_subsequence.py","code":"\"\"\"\nAuthor  : Mehdi ALAOUI\n\nThis is a pure Python implementation of Dynamic Programming solution to the longest\nincreasing subsequence of a given sequence.\n\nThe problem is:\n    Given an array, to find the longest and increasing sub-array in that given array and\n    return it.\n\nExample:\n    ``[10, 22, 9, 33, 21, 50, 41, 60, 80]`` as input will return\n    ``[10, 22, 33, 41, 60, 80]`` as output\n\"\"\"\n\nfrom __future__ import annotations\n\n\ndef longest_subsequence(array: list[int]) -> list[int]:  # This function is recursive\n    \"\"\"\n    Some examples\n\n    >>> longest_subsequence([10, 22, 9, 33, 21, 50, 41, 60, 80])\n    [10, 22, 33, 41, 60, 80]\n    >>> longest_subsequence([4, 8, 7, 5, 1, 12, 2, 3, 9])\n    [1, 2, 3, 9]\n    >>> longest_subsequence([28, 26, 12, 23, 35, 39])\n    [12, 23, 35, 39]\n    >>> longest_subsequence([9, 8, 7, 6, 5, 7])\n    [5, 7]\n    >>> longest_subsequence([1, 1, 1])\n    [1, 1, 1]\n    >>> longest_subsequence([])\n    []\n    \"\"\"\n    array_length = len(array)\n    # If the array contains only one element, we return it (it's the stop condition of\n    # recursion)\n    if array_length <= 1:\n        return array\n        # Else\n    pivot = array[0]\n    is_found = False\n    i = 1\n    longest_subseq: list[int] = []\n    while not is_found and i < array_length:\n        if array[i] < pivot:\n            is_found = True\n            temp_array = array[i:]\n            temp_array = longest_subsequence(temp_array)\n            if len(temp_array) > len(longest_subseq):\n                longest_subseq = temp_array\n        else:\n            i += 1\n\n    temp_array = [element for element in array[1:] if element >= pivot]\n    temp_array = [pivot, *longest_subsequence(temp_array)]\n    if len(temp_array) > len(longest_subseq):\n        return temp_array\n    else:\n        return longest_subseq\n\n\nif __name__ == \"__main__\":\n    import doctest\n\n    doctest.testmod()\n","hash":"6955d00f8efb821604c4357a9ccfa9ffe0d1d2a70dbce492269d276d05672e71","origins":[{"source":"algorithms","path":"dynamic_programming/longest_increasing_subsequence.py","url":"https://github.com/TheAlgorithms/Python/blob/25c712f2692449e91a57748d328ef34fccf25654/dynamic_programming/longest_increasing_subsequence.py","commit":"25c712f2692449e91a57748d328ef34fccf25654"}]}]},"topic-longestlineofconsecutiveoneinmatrix":{"key":"topic-longestlineofconsecutiveoneinmatrix","number":null,"title":"Longest Line of Consecutive One in Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Line of Consecutive One in Matrix.py","code":"class Solution:\n    def longestLine(self, M: List[List[int]]) -> int:\n        rowsLength = len(M)\n        if rowsLength == 0:\n            return 0\n        columnsLength = len(M[0])\n        rows = defaultdict(int)\n        cols = defaultdict(int)\n        ad = defaultdict(int)\n        dd = defaultdict(int)\n        maxCount = 0\n        for i in range(rowsLength):\n            for j in range(columnsLength):\n                if M[i][j] == 0:\n                    rows[i] = cols[j] = ad[j + i] = dd[j - i] = 0\n                else:\n                    rows[i] += 1\n                    cols[j] += 1\n                    ad[j + i] += 1\n                    dd[j - i] += 1\n                    maxCount = max(maxCount, rows[i], cols[j], ad[j + i], dd[j - i])\n        return maxCount","hash":"3d5b524c15bdff505c8c7305e3009423fea50c6aa45313da4bd9c64620e6f8b0","origins":[{"source":"solutions","path":"Mock Interviews/Google/Phone Interview 09/Longest Line of Consecutive One in Matrix.py"}]}],"sources":["solutions"]},"topic-longestmountaininarray":{"key":"topic-longestmountaininarray","number":null,"title":"Longest Mountain in Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Mountain in Array.py","code":"class Solution:\n    def longestMountain(self, A: List[int]) -> int:\n        result = base = 0\n        while base < len(A):\n            end = base\n            if end + 1 < len(A) and A[end] < A[end + 1]:\n                while end + 1 < len(A) and A[end] < A[end + 1]:\n                    end += 1\n                if end + 1 < len(A) and A[end] > A[end + 1]:\n                    while end + 1 < len(A) and A[end] > A[end + 1]:\n                        end += 1\n                    result = max(result, end - base + 1)\n            base = max(end, base + 1)\n        return result","hash":"a99ffea64e12b0002d7877414dede8c5555486568c9d5ff8716932ede6e02813","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Longest Mountain in Array.py"},{"source":"solutions","path":"Longest Mountain in Array.py"}]}],"sources":["solutions"]},"topic-longestnicesubstring":{"key":"topic-longestnicesubstring","number":null,"title":"Longest Nice Substring","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Nice Substring.py","code":"class Solution:\n    def longestNiceSubstring(self, s: str) -> str:\n        def isNice(s: str) -> bool:\n            charSet = set(s)\n            if len(charSet) % 2 == 1:\n                return False\n            for char in s:\n                if char >= 'A' and char <= 'Z':\n                    if chr(ord(char) + 32) not in charSet:\n                        return False\n                else:\n                    if chr(ord(char) - 32) not in charSet:\n                        return False\n            return True\n        result = ''\n        for i in range(len(s)):\n            for j in range(i + 1, len(s) + 1):\n                subString = s[i: j]\n                if isNice(subString) and len(subString) > len(result):\n                    result = subString\n        return result","hash":"dd67faeda0290bf96aaed3bb85eabf0a404794e2dd141396712eb74af77c21d1","origins":[{"source":"solutions","path":"Longest Nice Substring.py"}]}],"sources":["solutions"]},"topic-longestpalindromicsubsequence":{"key":"topic-longestpalindromicsubsequence","number":null,"title":"Longest Palindromic Subsequence","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Palindromic Subsequence.py","code":"class Solution:\n    def longestPalindromeSubseq(self, s: str) -> int:\n        n = len(s)\n\n        @lru_cache(None)\n        def helper(l, r):\n            if l > r:\n                return 0\n            if l == r:\n                return 1\n            if s[l] == s[r]:\n                return 2 + helper(l + 1, r - 1)\n            else:\n                return max(helper(l + 1, r), helper(l, r - 1))\n        \n        return helper(0, n - 1)","hash":"d2a5b8204c7b30a4e4c1377aeef23b9e8cd95ba010b4a063f09c1e68f0c09527","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Longest Palindromic Subsequence.py"}]}],"sources":["solutions"]},"topic-longestpathwithdifferentadjacentcharacters":{"key":"topic-longestpathwithdifferentadjacentcharacters","number":null,"title":"Longest Path With Different Adjacent Characters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Path With Different Adjacent Characters.py","code":"class Solution:\n    def longestPath(self, parent: List[int], s: str) -> int:\n        graph = defaultdict(set)\n        longestPath = 1\n        for i in range(1, len(parent)):\n            graph[parent[i]].add(i)\n        def dfs(node):\n            nonlocal longestPath\n            # if node is a leaf node\n            if node not in graph:\n                return 1\n            longestChain, secondLongestChain = 0, 0\n            for child in graph[node]:\n                longestChainStartingFromChild = dfs(child)\n                # if chracters are same at both parent and child, ignore\n                if s[node] == s[child]:\n                    continue\n                if longestChainStartingFromChild > longestChain:\n                    secondLongestChain = longestChain\n                    longestChain = longestChainStartingFromChild\n                elif longestChainStartingFromChild > secondLongestChain:\n                    secondLongestChain = longestChainStartingFromChild\n            longestPath = max(longestPath, 1 + longestChain + secondLongestChain)\n            return 1 + longestChain\n        dfs(0)\n        return longestPath","hash":"8cece3c8365c8f87749237f4fabab2613068057f09dcd7a756c5946d5e8fd329","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Longest Path With Different Adjacent Characters.py"}]}],"sources":["solutions"]},"topic-longestrepeatingsubstring":{"key":"topic-longestrepeatingsubstring","number":null,"title":"Longest Repeating Substring","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Repeating Substring.py","code":"class Solution:\n    def longestRepeatingSubstring(self, S: str) -> int:\n        n, base, modulus = len(S), 26, 2**24\n        nums = [ord(c) - ord('a') for c in S]\n        \n        def search(L):\n            h = 0\n            for i in range(L):\n                h = (h * base + nums[i]) % modulus\n            seen = {h}\n            baseL = pow(base, L, modulus)\n            for start in range(1, n - L + 1):\n                h = ((h * base) - (nums[start - 1] * baseL) + (nums[start + L - 1])) % modulus\n                if h in seen:\n                    return start\n                seen.add(h)\n            return -1\n        \n        left, right = 1, n\n        while left <= right:\n            L = left + (right - left) // 2\n            if search(L) != -1:\n                left = L + 1\n            else:\n                right = L - 1\n        return left - 1","hash":"2d7a61355af82cedb01e8d483cab1e57eb30398d4454975ec13fba7a20089d27","origins":[{"source":"solutions","path":"Longest Repeating Substring.py"}]}],"sources":["solutions"]},"topic-longestsubsequencewithlimitedsum":{"key":"topic-longestsubsequencewithlimitedsum","number":null,"title":"Longest Subsequence With Limited Sum","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Subsequence With Limited Sum.py","code":"class Solution:\n    def answerQueries(self, nums: List[int], queries: List[int]) -> List[int]:\n        prefixSum = sorted(nums)\n        for i in range(1, len(nums)):\n            prefixSum[i] += prefixSum[i - 1]\n        result = []\n        for query in queries:\n            index = bisect.bisect_right(prefixSum, query)\n            result.append(index)\n        return result","hash":"3023ea67137dd44fe0909b14a0295756ae81cafca98dcabd4a9b05bfd798ae94","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Longest Subsequence With Limited Sum.py"}]}],"sources":["solutions"]},"topic-longestsubstringwithatleastkrepeatingcharacters":{"key":"topic-longestsubstringwithatleastkrepeatingcharacters","number":null,"title":"Longest Substring with At Least K Repeating Characters","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Substring with At Least K Repeating Characters.py","code":"class Solution:\n    def longestSubstring(self, s: str, k: int) -> int:\n        countMap = Counter(s)\n        maxUnique, result = len(countMap), 0\n        for currUnique in range(1, maxUnique + 1):\n            countMap = defaultdict(int)\n            windowStart = windowEnd = unique = countAtLeastK = 0\n            while windowEnd < len(s):\n                if unique <= currUnique:\n                    if countMap[s[windowEnd]] == 0:\n                        unique += 1\n                    countMap[s[windowEnd]] += 1\n                    if countMap[s[windowEnd]] == k:\n                        countAtLeastK += 1\n                    windowEnd += 1\n                else:\n                    if countMap[s[windowStart]] == k:\n                        countAtLeastK -= 1\n                    countMap[s[windowStart]] -= 1\n                    if countMap[s[windowStart]] == 0:\n                        unique -= 1\n                    windowStart += 1\n                if unique == currUnique and unique == countAtLeastK:\n                    result = max(windowEnd - windowStart, result)\n        return result","hash":"3ecbd52110ca44eafda38a65d841e9d0e9ef9a4e2d39e2933b2f4e7696420e2c","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Longest Substring with At Least K Repeating Characters.py"}]}],"sources":["solutions"]},"topic-longestsubstringwithoutrepeatingcharacters01":{"key":"topic-longestsubstringwithoutrepeatingcharacters01","number":null,"title":"Longest Substring Without Repeating Characters 01","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Substring Without Repeating Characters-01.py","code":"class Solution:\n    def lengthOfLongestSubstring(self, s: str) -> int:\n        longestSubstring = 0\n        start = -1\n        end = 0\n        characterSet = set()\n        stringLength = len(s)\n        while start < stringLength and end < stringLength:\n            currentChar = s[end]\n            if currentChar in characterSet:\n                start += 1\n                characterToRemove = s[start]\n                characterSet.remove(characterToRemove)\n                longestSubstring = max(longestSubstring, end - start)\n            else:\n                characterSet.add(currentChar)\n                longestSubstring = max(longestSubstring, end - start)\n                end += 1\n        return longestSubstring","hash":"4666e860ea2b4e4674262e7c98698661ecf11ca712c550cc9cd4e40d6f5a57cb","origins":[{"source":"solutions","path":"Google Interview Questions/Longest Substring Without Repeating Characters-01.py"}]}],"sources":["solutions"]},"topic-longestsubstringwithoutrepeatingcharacters02":{"key":"topic-longestsubstringwithoutrepeatingcharacters02","number":null,"title":"Longest Substring Without Repeating Characters 02","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Substring Without Repeating Characters-02.py","code":"class Solution:\n    def lengthOfLongestSubstring(self, s: str) -> int:\n        longestSubstring = 0\n        characterMap = dict()\n        stringLength = len(s)\n        start, end = 0, 0\n        while end < stringLength:\n            if characterMap.get(s[end]):\n                start = max(characterMap.get(s[end]), start)\n            longestSubstring = max(longestSubstring, end - start + 1)\n            characterMap[s[end]] = end + 1\n            end += 1\n        return longestSubstring","hash":"710a52f3f9f935f64edc56b75d6fd680eb706c27bbe6a6300da962e6cfc452a3","origins":[{"source":"solutions","path":"Google Interview Questions/Longest Substring Without Repeating Characters-02.py"}]}],"sources":["solutions"]},"topic-longestuncommonsubsequencei":{"key":"topic-longestuncommonsubsequencei","number":null,"title":"Longest Uncommon Subsequence I","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Uncommon Subsequence I.py","code":"class Solution:\n    def findLUSlength(self, a: str, b: str) -> int:\n        if a == b:\n            return -1\n        return max(len(a), len(b))","hash":"a22b23b09f134ca1cd4b284f25b4667775d399ba9994052af21a7660659fb7d5","origins":[{"source":"solutions","path":"Longest Uncommon Subsequence I.py"}]}],"sources":["solutions"]},"topic-longestunivaluepath":{"key":"topic-longestunivaluepath","number":null,"title":"Longest Univalue Path","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Univalue Path.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def longestUnivaluePath(self, root: TreeNode) -> int:\n        longestPath = 0\n        \n        def longestArrow(node):\n            nonlocal longestPath\n            if node is None:\n                return 0\n            else:\n                leftLength = longestArrow(node.left)\n                rightLength = longestArrow(node.right)\n                leftArrowLength = rightArrowLength = 0\n                if node.left and node.left.val == node.val:\n                    leftArrowLength = leftLength + 1\n                if node.right and node.right.val == node.val:\n                    rightArrowLength = rightLength + 1\n                longestPath = max(longestPath, leftArrowLength + rightArrowLength)\n                return max(leftArrowLength, rightArrowLength)\n        \n        longestArrow(root)\n        return longestPath","hash":"ff50404432dc8fd3ca7d3504a0719360d68a8d76676389cf1c386d49e706167a","origins":[{"source":"solutions","path":"Longest Univalue Path.py"}]}],"sources":["solutions"]},"topic-longestwordindictionarythroughdeleting":{"key":"topic-longestwordindictionarythroughdeleting","number":null,"title":"Longest Word in Dictionary through Deleting","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest Word in Dictionary through Deleting.py","code":"class Solution:\n    def findLongestWord(self, s: str, d: List[str]) -> str:\n        def isSubsequence(x, y):\n            j = 0\n            for char in y:\n                if j < len(x) and x[j] == char:\n                    j += 1\n            return j == len(x)\n        result = ''\n        for string in d:\n            if isSubsequence(string, s):\n                if len(string) > len(result) or (len(string) == len(result) and string < result):\n                    result = string\n        return result","hash":"1dd8378ed4b449ccc60308b96c8141c59b9561ea351c15eeafd0ea4a4a7bf864","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Longest Word in Dictionary through Deleting.py"}]}],"sources":["solutions"]},"topic-longestzigzagpathinabinarytree":{"key":"topic-longestzigzagpathinabinarytree","number":null,"title":"Longest Zig Zag Path in a Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Longest ZigZag Path in a Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def longestZigZag(self, root: Optional[TreeNode]) -> int:\n        self.pathLength = 0\n        def dfs(node, goLeft, steps):\n            if node:\n                self.pathLength = max(self.pathLength, steps)\n                if goLeft:\n                    dfs(node.left, False, steps + 1)\n                    dfs(node.right, True, 1)\n                else:\n                    dfs(node.left, False, 1)\n                    dfs(node.right, True, steps + 1)\n        dfs(root, False, 0)\n        dfs(root, True, 0)\n        return self.pathLength","hash":"d10661325ee35aa4dcc1480f7234b79c09158fa24ed6f062c639bb92710f00ea","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-04 Leetcoding Challenge/Longest ZigZag Path in a Binary Tree.py"}]}],"sources":["solutions"]},"topic-lowestcommonancestorofabinarytreeiterative":{"key":"topic-lowestcommonancestorofabinarytreeiterative","number":null,"title":"Lowest Common Ancestor of a Binary Tree Iterative","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Lowest Common Ancestor of a Binary Tree - Iterative.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, x):\n#         self.val = x\n#         self.left = None\n#         self.right = None\n\nclass Solution:\n    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':\n        if root is None:\n            return None\n        stack = deque([root,])\n        parent = {root: None}\n        while stack:\n            node = stack.pop()\n            if node.left:\n                parent[node.left] = node\n                stack.append(node.left)\n            if node.right:\n                parent[node.right] = node\n                stack.append(node.right)\n        ancestors = set()\n        while p:\n            ancestors.add(p)\n            p = parent[p]\n        while q not in ancestors:\n            q = parent[q]\n        return q","hash":"4699a98bf71b866b684c701aa7660dacc27dfa3747aee0bf0b71e7665c6b1cff","origins":[{"source":"solutions","path":"Binary Tree/Lowest Common Ancestor of a Binary Tree - Iterative.py"}]}],"sources":["solutions"]},"topic-lowestcommonancestorofabinarytreerecursive":{"key":"topic-lowestcommonancestorofabinarytreerecursive","number":null,"title":"Lowest Common Ancestor of a Binary Tree Recursive","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Lowest Common Ancestor of a Binary Tree - Recursive.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, x):\n#         self.val = x\n#         self.left = None\n#         self.right = None\n\nclass Solution:\n    def lowestCommonAncestor(self, root: 'TreeNode', p: 'TreeNode', q: 'TreeNode') -> 'TreeNode':\n        def recurseTree(currentNode):\n            nonlocal result\n            if currentNode is None:\n                return False\n            left = recurseTree(currentNode.left)\n            right = recurseTree(currentNode.right)\n            mid = currentNode == p or currentNode == q\n            if left + mid + right >= 2:\n                result = currentNode\n            return left or mid or right\n        result = None\n        recurseTree(root)\n        return result","hash":"91b5f9065a650c97b68ae084c52bd75beef723bbc846684ccbce5082b3dee773","origins":[{"source":"solutions","path":"Binary Tree/Lowest Common Ancestor of a Binary Tree - Recursive.py"}]}],"sources":["solutions"]},"topic-magneticforcebetweentwoballs":{"key":"topic-magneticforcebetweentwoballs","number":null,"title":"Magnetic Force Between Two Balls","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Magnetic Force Between Two Balls.py","code":"class Solution:\n    def maxDistance(self, position: List[int], m: int) -> int:\n        position.sort()\n\n        def countBalls(distance: int):\n            answer, currentBucket = 1, position[0]\n            for i in range(1, len(position)):\n                if position[i] - currentBucket >= distance:\n                    answer, currentBucket = answer + 1, position[i]\n            return answer\n    \n        low, high, result = 0, position[-1] - position[0], position[-1] - position[0]\n        while low <= high:\n            mid = low + ((high - low) >> 1)\n            # too many balls placed, distance is too small, increase it\n            if countBalls(mid) >= m:\n                result, low = mid, mid + 1\n            # less balls placed, distance is too large, decrease it\n            else:\n                high = mid - 1\n        return result","hash":"a31b16003ba4715677d6e5df840a9399879313a30472f7f02f536263793d79a1","origins":[{"source":"solutions","path":"Magnetic Force Between Two Balls.py"}]}],"sources":["solutions"]},"topic-majorityelement":{"key":"topic-majorityelement","number":null,"title":"Majority Element","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Majority Element.py","code":"class Solution:\n    def majorityElement(self, nums: List[int]) -> int:\n        count, candidate = 0, None\n        for num in nums:\n            if count == 0:\n                candidate = num\n                count += 1\n            elif num == candidate:\n                count += 1\n            else:\n                count -= 1\n        return candidate","hash":"fcb885573112bc6734d83bc15bb404ebd0f6722d109c19a87e11462d146a106f","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-02 Leetcoding Challenge/Majority Element.py"},{"source":"solutions","path":"Majority Element.py"}]}],"sources":["solutions"]},"topic-majorityelementii":{"key":"topic-majorityelementii","number":null,"title":"Majority Element II","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Majority Element II.py","code":"class Solution:\n    def majorityElement(self, nums: List[int]) -> List[int]:\n        if not nums:\n            return []\n        candidate1, count1, candidate2, count2 = None, 0, None, 0\n        for num in nums:\n            if candidate1 == num:\n                count1 += 1\n            elif candidate2 == num:\n                count2 += 1\n            elif count1 == 0:\n                candidate1 = num\n                count1 += 1\n            elif count2 == 0:\n                candidate2 = num\n                count2 += 1\n            else:\n                count1 -= 1\n                count2 -= 1\n        result = []\n        for candidate in [candidate1, candidate2]:\n            if nums.count(candidate) > len(nums) // 3:\n                result.append(candidate)\n        return result","hash":"2bb32357d39c1ab6d6b88232edc334bc122f61a1478913a2a154f5ffd65571dc","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Majority Element II.py"}]}],"sources":["solutions"]},"topic-makearrayzerobysubtractingequalamounts":{"key":"topic-makearrayzerobysubtractingequalamounts","number":null,"title":"Make Array Zero by Subtracting Equal Amounts","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Make Array Zero by Subtracting Equal Amounts.py","code":"class Solution:\n    def minimumOperations(self, nums: List[int]) -> int:\n        hashSet = set(nums)\n        return len(hashSet) - 1 if 0 in hashSet else len(hashSet)","hash":"623a0a92d70a55e2c8fe7034a559efe00711917346c42c39ed279335544abfad","origins":[{"source":"solutions","path":"Make Array Zero by Subtracting Equal Amounts.py"}]}],"sources":["solutions"]},"topic-makesumdivisiblebyp":{"key":"topic-makesumdivisiblebyp","number":null,"title":"Make Sum Divisible by P","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Make Sum Divisible by P.py","code":"class Solution:\n    def minSubarray(self, nums: List[int], p: int) -> int:\n        remainder = sum(nums) % p\n        if remainder == 0:\n            return 0\n        length = len(nums)\n        hashMap = {0: -1}\n        runningSum = [0]\n        for i, num in enumerate(nums):\n            runningSum.append(runningSum[-1] + num)\n            currentRemainder = runningSum[-1] % p\n            if currentRemainder >= remainder:\n                if currentRemainder - remainder in hashMap:\n                    length = min(length, i - hashMap[currentRemainder - remainder])\n            else:\n                if p - remainder + currentRemainder in hashMap:\n                    length = min(length, i - hashMap[p - remainder + currentRemainder])\n            hashMap[currentRemainder] = i\n        if length == len(nums):\n            return -1\n        return length","hash":"91438db7b34d562ebab0a347cf9260c4e749665d8579bb92e3624451c4fcea95","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 35/Make Sum Divisible by P.py"}]}],"sources":["solutions"]},"topic-maketwoarraysequalbyreversingsubarrays":{"key":"topic-maketwoarraysequalbyreversingsubarrays","number":null,"title":"Make Two Arrays Equal by Reversing Sub arrays","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Make Two Arrays Equal by Reversing Sub-arrays.py","code":"class Solution:\n    def canBeEqual(self, target: List[int], arr: List[int]) -> bool:\n        return sorted(target) == sorted(arr)","hash":"4210293ee4f1c63300e11d8aa7cec97e339a2b712a731b865c0d82f349cfc309","origins":[{"source":"solutions","path":"Make Two Arrays Equal by Reversing Sub-arrays.py"}]}],"sources":["solutions"]},"topic-makingalargeisland":{"key":"topic-makingalargeisland","number":null,"title":"Making A Large Island","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Making A Large Island.py","code":"class Solution:\n    def largestIsland(self, grid: List[List[int]]) -> int:\n        N, area, index = len(grid), {}, 2\n        def neighbours(r, c):\n            for nr, nc in ((r - 1, c), (r, c - 1), (r + 1, c), (r, c + 1)):\n                if 0 <= nr < N and 0 <= nc < N:\n                    yield nr, nc\n        def dfs(r, c, index):\n            result = 1\n            grid[r][c] = index\n            for nr, nc in neighbours(r, c):\n                if grid[nr][nc] == 1:\n                    result += dfs(nr, nc, index)\n            return result\n        for r in range(N):\n            for c in range(N):\n                if grid[r][c] == 1:\n                    area[index] = dfs(r, c, index)\n                    index += 1\n        result = max(area.values() or [0])\n        for r in range(N):\n            for c in range(N):\n                if grid[r][c] == 0:\n                    seen = {grid[nr][nc] for nr, nc in neighbours(r, c) if grid[nr][nc] > 1}\n                    result = max(result, 1 + sum(area[i] for i in seen))\n        return result","hash":"cd12dce9afedac021be4f24a229765466eaba1820dc9ff020a2608418ff2625a","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-08 LeetCoding Challenge/Making A Large Island.py"}]}],"sources":["solutions"]},"topic-makingfilenamesunique":{"key":"topic-makingfilenamesunique","number":null,"title":"Making File Names Unique","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Making File Names Unique.py","code":"class Solution:\n    def getFolderNames(self, names: List[str]) -> List[str]:\n        hashMap, result = defaultdict(int), []\n        for name in names:\n            currentName = name\n            while currentName in hashMap:\n                hashMap[name] += 1\n                currentName = name + '(' + str(hashMap[name]) + ')'\n            result.append(currentName)\n            hashMap[currentName] = 0\n        return result","hash":"8a0e17bfd31f760e75a48c8bb08f755a365cb2775a69639ad1a30b0aac527530","origins":[{"source":"solutions","path":"Making File Names Unique.py"}]}],"sources":["solutions"]},"topic-mapsumpairs":{"key":"topic-mapsumpairs","number":null,"title":"Map Sum Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Map Sum Pairs.py","code":"class TrieNode:\n    \n    def __init__(self):\n        self.children = {}\n        self.score = 0\n\nclass MapSum:\n\n    def __init__(self):\n        \"\"\"\n        Initialize your data structure here.\n        \"\"\"\n        self.root = TrieNode()\n        self.keyValueMap = defaultdict(int)\n\n    def insert(self, key: str, val: int) -> None:\n        delta = val - self.keyValueMap[key]\n        self.keyValueMap[key] = val\n        current = self.root\n        current.score += delta\n        for char in key:\n            current = current.children.setdefault(char, TrieNode())\n            current.score += delta\n\n    def sum(self, prefix: str) -> int:\n        current = self.root\n        for char in prefix:\n            if char not in current.children:\n                return 0\n            current = current.children[char]\n        return current.score\n\n\n# Your MapSum object will be instantiated and called as such:\n# obj = MapSum()\n# obj.insert(key,val)\n# param_2 = obj.sum(prefix)","hash":"12cd3357c17ed6ab284d6ab2441679962bd6b008405469fc185b65bd658375b3","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-07 Leetcoding Challenge/Map Sum Pairs.py"},{"source":"solutions","path":"Trie/Map Sum Pairs.py"}]}],"sources":["solutions"]},"topic-maxconsecutiveones":{"key":"topic-maxconsecutiveones","number":null,"title":"Max Consecutive Ones","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Max Consecutive Ones.py","code":"class Solution:\n    def findMaxConsecutiveOnes(self, nums: List[int]) -> int:\n        oneCount, maxOneCount = 0, 0\n        for num in nums:\n            if num == 1:\n                oneCount += 1\n            else:\n                oneCount = 0\n            maxOneCount = max(maxOneCount, oneCount)\n        return maxOneCount","hash":"8b454a5bbffd36e6c19098f4bd2a91b771655cb93b1c1e6bfd807a368ea12ce2","origins":[{"source":"solutions","path":"Arrays/Max Consecutive Ones.py"}]}],"sources":["solutions"]},"topic-maxconsecutiveonesiii":{"key":"topic-maxconsecutiveonesiii","number":null,"title":"Max Consecutive Ones III","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Max Consecutive Ones III.py","code":"class Solution:\n    def longestOnes(self, nums: List[int], k: int) -> int:\n        left = 0\n        for right in range(len(nums)):\n            k -= (1 - nums[right])\n            if k < 0:\n                k += (1 - nums[left])\n                left += 1\n        return right - left + 1","hash":"65ea3a2c03bdbf9d4a92e821c3321c2b706a1abadccf425c93d2659fa9440989","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-06 Leetcoding Challenge/Max Consecutive Ones III.py"}]}],"sources":["solutions"]},"topic-maxnumberofksumpairs":{"key":"topic-maxnumberofksumpairs","number":null,"title":"Max Number of K Sum Pairs","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Max Number of K-Sum Pairs.py","code":"class Solution:\n    def maxOperations(self, nums: List[int], k: int) -> int:\n        result, freqMap = 0, defaultdict(int)\n        for num in nums:\n            if freqMap[k - num] > 0:\n                result += 1\n                freqMap[k - num] -= 1\n            else:\n                freqMap[num] += 1\n        return result","hash":"ebe44db048a3de902d600f0ef45960b240e627b51377c43ec92e4aa0219868c1","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Max Number of K-Sum Pairs.py"}]}],"sources":["solutions"]},"topic-maxpairsuminanarray":{"key":"topic-maxpairsuminanarray","number":null,"title":"Max Pair Sum in an Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Max Pair Sum in an Array.py","code":"class Solution:\n    def maxSum(self, nums: List[int]) -> int:\n        def getMaximumDigit(num: int) -> int:\n            result, temp = 0, num\n            while temp > 0:\n                digit = temp % 10\n                temp //= 10\n                result = max(result, digit)\n            return result\n\n        hashMap = defaultdict(list)\n        for num in nums:\n            maxDigit = getMaximumDigit(num)\n            hashMap[maxDigit].append(num)\n        result = -1\n        for values in hashMap.values():\n            for i1, num1 in enumerate(values):\n                for i2, num2 in enumerate(values):\n                    if i1 == i2:\n                        continue\n                    result = max(result, num1 + num2)\n        return result","hash":"ff778aae9372421ae02754559da698fe8bd2ff7161bc8a6830e04d694d6d1570","origins":[{"source":"solutions","path":"Max Pair Sum in an Array.py"}]}],"sources":["solutions"]},"topic-maximalsquare":{"key":"topic-maximalsquare","number":null,"title":"Maximal Square","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximal Square.py","code":"class Solution:\n    def maximalSquare(self, matrix: List[List[str]]) -> int:\n        rows, cols, maxSqLen, prev = len(matrix), len(matrix[0]) if len(matrix) > 0 else 0, 0, 0\n        dp = [0] * (cols + 1)\n        for i in range(1, rows + 1):\n            for j in range(1, cols + 1):\n                temp = dp[j]\n                if matrix[i - 1][j - 1] == '1':\n                    dp[j] = min(prev, dp[j], dp[j - 1]) + 1\n                    maxSqLen = max(maxSqLen, dp[j])\n                else:\n                    dp[j] = 0\n                prev = temp\n        return maxSqLen * maxSqLen","hash":"c57b71e3121053f551719d308207e75230990f1a262a32f3fe87ce43e78ea1b1","origins":[{"source":"solutions","path":"Maximal Square.py"}]}],"sources":["solutions"]},"topic-maximizedistancetoclosestperson":{"key":"topic-maximizedistancetoclosestperson","number":null,"title":"Maximize Distance to Closest Person","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximize Distance to Closest Person.py","code":"class Solution:\n    def maxDistToClosest(self, seats: List[int]) -> int:\n        result = seats.index(1)\n        seats.reverse()\n        result = max(seats.index(1), result)\n        for seat, group in groupby(seats):\n            if not seat:\n                emptySeatsLength = len(list(group))\n                result = max(result, (emptySeatsLength + 1) // 2)\n        return result","hash":"49b9573814135061c1415403258db4b46ea6c50837b66a46245c31aa6bfdae6d","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Maximize Distance to Closest Person.py"}]},{"language":"python","name":"Maximize Distance to Closest Person.py","code":"class Solution:\n    def maxDistToClosest(self, seats: List[int]) -> int:\n        people = (i for i, seat in enumerate(seats) if seat)\n        prev, future = None, next(people)\n        result = 0\n        for i, seat in enumerate(seats):\n            if seat:\n                prev = i\n            else:\n                while future is not None and future < i:\n                    future = next(people, None)\n                left = float('inf') if prev is None else i - prev\n                right = float('inf') if future is None else future - i\n                result = max(result, min(left, right))\n        return result","hash":"22c6c34ee80b7c3769af7b26b9e60bfa6874270f721e39af4d6b9da43c985e1a","origins":[{"source":"solutions","path":"Mock Interviews/Google/Online Assessment 09/Maximize Distance to Closest Person.py"}]}],"sources":["solutions"]},"topic-maximizesumofarrayafterknegations":{"key":"topic-maximizesumofarrayafterknegations","number":null,"title":"Maximize Sum Of Array After K Negations","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximize Sum Of Array After K Negations.py","code":"class Solution:\n    def largestSumAfterKNegations(self, nums: List[int], k: int) -> int:\n        heapq.heapify(nums)\n        for i in range(k):\n            val = heapq.heappop(nums)\n            heapq.heappush(nums, -val)\n        return sum(nums)","hash":"eb75e2de900bd18ef2cdf912ab98872461aeddba2894dedd696f6d7942e0ccd0","origins":[{"source":"solutions","path":"Maximize Sum Of Array After K Negations.py"}]}],"sources":["solutions"]},"topic-maximumbagswithfullcapacityofrocks":{"key":"topic-maximumbagswithfullcapacityofrocks","number":null,"title":"Maximum Bags With Full Capacity of Rocks","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Bags With Full Capacity of Rocks.py","code":"class Solution:\n    def maximumBags(self, capacity: List[int], rocks: List[int], additionalRocks: int) -> int:\n        diffArray = [(capacity[i] - rocks[i]) for i in range(len(rocks))]\n        diffArray.sort()\n        result, i = 0, 0\n        while additionalRocks > 0 and i < len(rocks) and diffArray[i] <= additionalRocks:\n            result, additionalRocks, i = result + 1, additionalRocks - diffArray[i], i + 1\n        return result","hash":"2be1d1de160c90c142411ea8ca14e0383c096872338e7b222b1ba7c8660f3477","origins":[{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Maximum Bags With Full Capacity of Rocks.py"}]}],"sources":["solutions"]},"topic-maximumbinarytree":{"key":"topic-maximumbinarytree","number":null,"title":"Maximum Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def constructMaximumBinaryTree(self, nums: List[int]) -> Optional[TreeNode]:\n        def getMaxIndex(left: int, right: int) -> int:\n            maxIndex = left\n            for i in range(left + 1, right):\n                if nums[maxIndex] < nums[i]:\n                    maxIndex = i\n            return maxIndex\n        def construct(left: int, right: int) -> Optional[TreeNode]:\n            if left == right:\n                return None\n            maxIndex = getMaxIndex(left, right)\n            return TreeNode(nums[maxIndex], construct(left, maxIndex), construct(maxIndex + 1, right))\n        return construct(0, len(nums))","hash":"712df5c8b274f7a15e04dcef3d3bd8bcd33cf699d41abf5c8304b7131d00549e","origins":[{"source":"solutions","path":"Maximum Binary Tree.py"}]}],"sources":["solutions"]},"topic-maximumdepthofnarytree":{"key":"topic-maximumdepthofnarytree","number":null,"title":"Maximum Depth of N ary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Depth of N-ary Tree.py","code":"\"\"\"\n# Definition for a Node.\nclass Node:\n    def __init__(self, val=None, children=None):\n        self.val = val\n        self.children = children\n\"\"\"\n\nclass Solution:\n    def maxDepth(self, root: 'Node') -> int:\n        depth, stack = 0, deque()\n        if root is not None:\n            stack.append((1, root))\n        while stack:\n            currentDepth, node = stack.pop()\n            if node is not None:\n                depth = max(depth, currentDepth)\n                for c in node.children:\n                    stack.append((currentDepth + 1, c))\n        return depth","hash":"68885e7dec35b426e760ece713eb8ef83c051dd3c17031d4cb11c11581fdd720","origins":[{"source":"solutions","path":"N-ary Tree/Maximum Depth of N-ary Tree.py"}]}],"sources":["solutions"]},"topic-maximumdifferencebetweennodeandancestor":{"key":"topic-maximumdifferencebetweennodeandancestor","number":null,"title":"Maximum Difference Between Node and Ancestor","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Difference Between Node and Ancestor.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def maxAncestorDiff(self, root: TreeNode) -> int:\n        if not root:\n            return 0\n        def getDiff(node, maxVal, minVal):\n            if node is None:\n                return abs(maxVal - minVal)\n            maxVal = max(maxVal, node.val)\n            minVal = min(minVal, node.val)\n            left = getDiff(node.left, maxVal, minVal)\n            right = getDiff(node.right, maxVal, minVal)\n            return max(left, right)\n        return getDiff(root, root.val, root.val)","hash":"054978f07c70cd91ffa9f07928067c649f71037b3e0a15706b467f9ec2cdeaa9","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-11 Leetcoding Challenge/Maximum Difference Between Node and Ancestor.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Maximum Difference Between Node and Ancestor.py"}]}],"sources":["solutions"]},"topic-maximumdistanceinarrays":{"key":"topic-maximumdistanceinarrays","number":null,"title":"Maximum Distance in Arrays","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Distance in Arrays.py","code":"class Solution:\n    def maxDistance(self, arrays: List[List[int]]) -> int:\n        result, minValue, maxValue = 0, arrays[0][0], arrays[0][-1]\n        for array in arrays[1:]:\n            result = max(result, abs(maxValue - array[0]), abs(array[-1] - minValue))\n            minValue = min(minValue, array[0])\n            maxValue = max(maxValue, array[-1])\n        return result","hash":"fb1cad694c0a96bb85d297eebdc1da035bf1885291d24c28e62b1e1701fe4089","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-10 Leetcoding Challenge/Maximum Distance in Arrays.py"}]}],"sources":["solutions"]},"topic-maximumelementafterdecreasingandrearranging":{"key":"topic-maximumelementafterdecreasingandrearranging","number":null,"title":"Maximum Element After Decreasing and Rearranging","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Element After Decreasing and Rearranging.py","code":"class Solution:\n    def maximumElementAfterDecrementingAndRearranging(self, arr: List[int]) -> int:\n        arr = sorted(arr)\n        if arr[0] != 1:\n            arr[0] = 1\n        for i in range(1, len(arr)):\n            if abs(arr[i] - arr[i - 1]) > 1:\n                arr[i] = arr[i - 1] + 1\n        return arr[-1]","hash":"25489c3ca7aa8ef5ec5e713598f93c3dff1ad85c9f6d659dcc6bf433dbc454d6","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 51/Maximum Element After Decreasing and Rearranging.py"}]}],"sources":["solutions"]},"topic-maximumfrequencystack":{"key":"topic-maximumfrequencystack","number":null,"title":"Maximum Frequency Stack","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Frequency Stack.py","code":"class FreqStack:\n\n    def __init__(self):\n        self.freq, self.freqGroup, self.maxFreq = Counter(), defaultdict(list), 0\n\n    def push(self, x: int) -> None:\n        freq = self.freq[x] + 1\n        self.freq[x] = freq\n        self.freqGroup[freq].append(x)\n        if freq > self.maxFreq:\n            self.maxFreq = freq\n\n    def pop(self) -> int:\n        x = self.freqGroup[self.maxFreq].pop()\n        self.freq[x] -= 1\n        if not self.freqGroup[self.maxFreq]:\n            self.maxFreq -= 1\n        return x\n\n# Your FreqStack object will be instantiated and called as such:\n# obj = FreqStack()\n# obj.push(x)\n# param_2 = obj.pop()","hash":"8e107e059f3bb0e8611f1d7781d01513248511766c3085c9e5372c5c49805419","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-02 Leetcoding Challenge/Maximum Frequency Stack.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-03 Leetcoding Challenge/Maximum Frequency Stack.py"}]}],"sources":["solutions"]},"topic-maximumicecreambars":{"key":"topic-maximumicecreambars","number":null,"title":"Maximum Ice Cream Bars","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Ice Cream Bars.py","code":"class Solution:\n    def maxIceCream(self, costs: List[int], coins: int) -> int:\n        costs.sort()\n        result = 0\n        for cost in costs:\n            if cost <= coins:\n                result += 1\n                coins -= cost\n            else:\n                break\n        return result","hash":"29a02b70cdf5eb7ae613d392fd6fc064fa54ae0b2321e9cf08833ad2777ac308","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Maximum Ice Cream Bars.py"}]}],"sources":["solutions"]},"topic-maximumlengthofpairchain":{"key":"topic-maximumlengthofpairchain","number":null,"title":"Maximum Length of Pair Chain","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Length of Pair Chain.py","code":"class Solution:\n    def findLongestChain(self, pairs: List[List[int]]) -> int:\n        pairs.sort(key = lambda x : (x[1], x[0]))\n        result, currentPairEnd = 1, pairs[0][1]\n        for pair in pairs[1:]:\n            if currentPairEnd < pair[0]:\n                result, currentPairEnd = result + 1, pair[1]\n        return result","hash":"a466d491b53b0c76de69e2ceb178fe2cd68739d9f1e1bdb0b500fa2e2c25f9d5","origins":[{"source":"solutions","path":"Maximum Length of Pair Chain.py"}]}],"sources":["solutions"]},"topic-maximumlengthofsubarraywithpositiveproduct":{"key":"topic-maximumlengthofsubarraywithpositiveproduct","number":null,"title":"Maximum Length of Subarray With Positive Product","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Length of Subarray With Positive Product.py","code":"class Solution:\n    def getMaxLen(self, nums: List[int]) -> int:\n        positiveNumbers, negativeNumbers, maxLength = 0, 0, 0\n        for num in nums:\n            if num == 0:\n                positiveNumbers, negativeNumbers = 0, 0\n            elif num > 0:\n                positiveNumbers += 1\n                if negativeNumbers != 0:\n                    negativeNumbers += 1\n                maxLength = max(maxLength, positiveNumbers)\n            else:\n                positiveNumbers, negativeNumbers = negativeNumbers, positiveNumbers\n                negativeNumbers += 1\n                if positiveNumbers != 0:\n                    positiveNumbers += 1\n                maxLength = max(maxLength, positiveNumbers)\n        return maxLength","hash":"818dfc24ca2394491035a14d80004e976179fb87cce1f31c2ba104ee4d5d319a","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 204/Maximum Length of Subarray With Positive Product.py"}]}],"sources":["solutions"]},"topic-maximumnestingdepthoftheparentheses":{"key":"topic-maximumnestingdepthoftheparentheses","number":null,"title":"Maximum Nesting Depth of the Parentheses","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Nesting Depth of the Parentheses.py","code":"class Solution:\n    def maxDepth(self, s: str) -> int:\n        depth = maxDepth = 0\n        for char in s:\n            if char == '(':\n                depth += 1\n                maxDepth = max(maxDepth, depth)\n            elif char == ')':\n                depth -= 1\n        return maxDepth","hash":"9cb5a7171c25a5dcfd541bb04ae8ab9334a944c0fb46c5a8aa39a3d8ec52be53","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 210/Maximum Nesting Depth of the Parentheses.py"}]}],"sources":["solutions"]},"topic-maximumnonnegativeproductinamatrix":{"key":"topic-maximumnonnegativeproductinamatrix","number":null,"title":"Maximum Non Negative Product in a Matrix","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Non Negative Product in a Matrix.py","code":"class Solution:\n    def maxProductPath(self, grid: List[List[int]]) -> int:\n        if len(grid) == 0 or len(grid[0]) == 0:\n            return 0\n        rows, cols = len(grid), len(grid[0])\n        productDP = [[[float('-inf'), float('inf')] for _ in range(cols)] for _ in range(rows)]\n        productDP[0][0] = [max(productDP[0][0][0], grid[0][0]), min(productDP[0][0][1], grid[0][0])]\n        for row in range(1, rows):\n            tempMax = max(grid[row][0] * productDP[row - 1][0][0], grid[row][0] * productDP[row - 1][0][1], productDP[row][0][0])\n            tempMin = min(grid[row][0] * productDP[row - 1][0][0], grid[row][0] * productDP[row - 1][0][1], productDP[row][0][1])\n            productDP[row][0] = [tempMax, tempMin]\n        for col in range(1, cols):\n            tempMax = max(grid[0][col] * productDP[0][col - 1][0], grid[0][col] * productDP[0][col - 1][1], productDP[0][col][0])\n            tempMin = min(grid[0][col] * productDP[0][col - 1][0], grid[0][col] * productDP[0][col - 1][1], productDP[0][col][1])\n            productDP[0][col] = [tempMax, tempMin]\n        for row in range(1, rows):\n            for col in range(1, cols):\n                tempMax = max(grid[row][col] * productDP[row - 1][col][0], grid[row][col] * productDP[row - 1][col][1], productDP[row][col][0], grid[row][col] * productDP[row][col - 1][0], grid[row][col] * productDP[row][col - 1][1])\n                tempMin = min(grid[row][col] * productDP[row - 1][col][0], grid[row][col] * productDP[row - 1][col][1], productDP[row][col][1], grid[row][col] * productDP[row][col - 1][0], grid[row][col] * productDP[row][col - 1][1])\n                productDP[row][col] = [tempMax, tempMin]\n        result = max(productDP[rows - 1][cols - 1][0], productDP[rows - 1][cols - 1][1])\n        return -1 if result < 0 else result % (10 ** 9 + 7)","hash":"40d5f6cbd4935f6a94b20cb900be6af1da9243597dd7a1850d84ee550e691497","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 207/Maximum Non Negative Product in a Matrix.py"}]}],"sources":["solutions"]},"topic-maximumnumberofballoons":{"key":"topic-maximumnumberofballoons","number":null,"title":"Maximum Number of Balloons","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Number of Balloons.py","code":"class Solution:\n    def maxNumberOfBalloons(self, text: str) -> int:\n        freqMap = Counter(text)\n        return min(freqMap['b'], freqMap['a'], freqMap['n'], freqMap['l'] // 2, freqMap['o'] // 2)","hash":"e659d951057513ba548c15cfbb199d0634f0e696feddc250209e3127449b849e","origins":[{"source":"solutions","path":"Maximum Number of Balloons.py"}]}],"sources":["solutions"]},"topic-maximumnumberofballsinabox":{"key":"topic-maximumnumberofballsinabox","number":null,"title":"Maximum Number of Balls in a Box","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Number of Balls in a Box.py","code":"class Solution:\n    def countBalls(self, lowLimit: int, highLimit: int) -> int:\n        freqMap = defaultdict(int)\n        def digitSum(num: int):\n            result = 0\n            while num > 0:\n                result += num % 10\n                num = num // 10\n            return result\n        for num in range(lowLimit, highLimit + 1):\n            freqMap[digitSum(num)] += 1\n        return max(freqMap.values())","hash":"af752ba233451af80a50720ed61e2c32abf1c4ad48075c3e4cf993fd7f9b6eb1","origins":[{"source":"solutions","path":"Maximum Number of Balls in a Box.py"}]}],"sources":["solutions"]},"topic-maximumnumberofcoinsyoucanget":{"key":"topic-maximumnumberofcoinsyoucanget","number":null,"title":"Maximum Number of Coins You Can Get","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Number of Coins You Can Get.py","code":"class Solution:\n    def maxCoins(self, piles: List[int]) -> int:\n        piles.sort(reverse = True)\n        coins, numberOfPiles = 0, len(piles)\n        for i in range(1, numberOfPiles - (numberOfPiles // 3), 2):\n            coins += piles[i]\n        return coins","hash":"725611b6bfddbe83805e0a4a06367094a793e24379f98e96bfcf41c71215d961","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 203/Maximum Number of Coins You Can Get.py"}]}],"sources":["solutions"]},"topic-maximumnumberofpairsinarray":{"key":"topic-maximumnumberofpairsinarray","number":null,"title":"Maximum Number of Pairs in Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Number of Pairs in Array.py","code":"class Solution:\n    def numberOfPairs(self, nums: List[int]) -> List[int]:\n        freqMap = Counter(nums)\n        result = [0, 0]\n        for freq in freqMap.values():\n            result[0] += freq // 2\n            result[1] += freq % 2\n        return result","hash":"c974b3269cad561b9847ece156bd69f0bfbaf8b270c8a48570de634e14a44217","origins":[{"source":"solutions","path":"Maximum Number of Pairs in Array.py"}]}],"sources":["solutions"]},"topic-maximumnumberofvisiblepoints":{"key":"topic-maximumnumberofvisiblepoints","number":null,"title":"Maximum Number of Visible Points","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Number of Visible Points.py","code":"class Solution:\n    def visiblePoints(self, points: List[List[int]], angle: int, location: List[int]) -> int:\n        radiansArray, onPlayerPoints = [], 0\n        for point in points:\n            if point[0] == location[0] and point[1] == location[1]:\n                onPlayerPoints += 1\n            else:\n                radiansArray.append(math.atan2(point[1] - location[1], point[0] - location[0]))\n        radiansArray.sort()\n        radiansArray = radiansArray + [i + (2 * math.pi) for i in radiansArray[:-1]]\n        angle = angle * (math.pi / 180)\n        left = result = 0\n        for right in range(len(radiansArray)):\n            while radiansArray[left] < radiansArray[right] - angle:\n                left += 1\n            result = max(result, right - left + 1)\n        return result + onPlayerPoints","hash":"92ea021d10838594e04999cb84494b4ac1d324cd086a58ba02e269796505b0b6","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 209/Maximum Number of Visible Points.py"}]}],"sources":["solutions"]},"topic-maximumnumberofwordsyoucantype":{"key":"topic-maximumnumberofwordsyoucantype","number":null,"title":"Maximum Number of Words You Can Type","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Number of Words You Can Type.py","code":"class Solution:\n    def canBeTypedWords(self, text: str, brokenLetters: str) -> int:\n        result, brokenSet = 0, set(brokenLetters)\n        for word in text.split(' '):\n            invalid = False\n            for char in word:\n                if char in brokenSet:\n                    invalid = True\n                    break\n            if not invalid:\n                result += 1\n        return result","hash":"a1aba6df1ff48fc1e85472559ba97d3cd240df54064d4ff2a51eb71c5723d216","origins":[{"source":"solutions","path":"Maximum Number of Words You Can Type.py"}]}],"sources":["solutions"]},"topic-maximumproductofsplittedbinarytree":{"key":"topic-maximumproductofsplittedbinarytree","number":null,"title":"Maximum Product of Splitted Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Product of Splitted Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def maxProduct(self, root: Optional[TreeNode]) -> int:\n        prefixSums = []\n        def dfs(node):\n            if node is None:\n                return 0\n            currentSum = dfs(node.left) + dfs(node.right) + node.val\n            prefixSums.append(currentSum)\n            return currentSum\n        result, totalSum = float('-inf'), dfs(root)\n        for s in prefixSums:\n            result = max(result, s * (totalSum - s))\n        return result % (10**9 + 7)","hash":"e4df16fbc8bc0cbf71a73b9e6e4a73296479323e6248e2d34a2fdd62ae6313bb","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-08 LeetCoding Challenge/Maximum Product of Splitted Binary Tree.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-12 Leetcoding Challenge/Maximum Product of Splitted Binary Tree.py"}]}],"sources":["solutions"]},"topic-maximumproductofthreenumbers":{"key":"topic-maximumproductofthreenumbers","number":null,"title":"Maximum Product of Three Numbers","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Product of Three Numbers.py","code":"class Solution:\n    def maximumProduct(self, nums: List[int]) -> int:\n        # min1, min2, .... max3, max2, max1\n        min1, min2, max3, max2, max1 = float('inf'), float('inf'), float('-inf'), float('-inf'), float('-inf')\n        for num in nums:\n            if num <= min1:\n                min2, min1 = min1, num\n            elif num <= min2:\n                min2 = num\n            if num >= max1:\n                max3, max2, max1 = max2, max1, num\n            elif num >= max2:\n                max3, max2 = max2, num\n            elif num >= max3:\n                max3 = num\n        return max(max1 * max2 * max3, max1 * min1 * min2)","hash":"fc6507e8211be2e9f16b891c741d9aeb89d96bdb9faaeae41e4050c1306ebc64","origins":[{"source":"solutions","path":"Maximum Product of Three Numbers.py"}]}],"sources":["solutions"]},"topic-maximumproductoftwoelementsinanarray":{"key":"topic-maximumproductoftwoelementsinanarray","number":null,"title":"Maximum Product of Two Elements in an Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Product of Two Elements in an Array.py","code":"class Solution:\n    def maxProduct(self, nums: List[int]) -> int:\n        nums.sort(reverse = True)\n        return (nums[0] - 1) * (nums[1] - 1)","hash":"4bc3a94e6fe3ddee43ff8ea51c89ee0390363362b1da24a28a405cb8f9f653a6","origins":[{"source":"solutions","path":"Maximum Product of Two Elements in an Array.py"}]}],"sources":["solutions"]},"topic-maximumproductofwordlengths":{"key":"topic-maximumproductofwordlengths","number":null,"title":"Maximum Product of Word Lengths","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Product of Word Lengths.py","code":"class Solution:\n    def maxProduct(self, words: List[str]) -> int:\n        n, maxVal = len(words), 0\n        masks, lens = [0] * n, [0] * n\n        bitNumber = lambda ch: ord(ch) - ord('a')\n        for i in range(n):\n            bitMask = 0\n            for ch in words[i]:\n                # add bit number bitNumber in bitMask\n                bitMask |= 1 << bitNumber(ch)\n            masks[i] = bitMask\n            lens[i] = len(words[i])\n        for i in range(n):\n            for j in range(i + 1, n):\n                if masks[i] & masks[j] == 0:\n                    maxVal = max(maxVal, lens[i] * lens[j])\n        return maxVal","hash":"97f5f5e984b81a45c90ff9cf12582b76b6ff47cdd4d4a8e193e99808e6218922","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-05 Leetcoding Challenge/Maximum Product of Word Lengths.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-05 Leetcoding Challenge/Maximum Product of Word Lengths.py"}]}],"sources":["solutions"]},"topic-maximumproductsubarray":{"key":"topic-maximumproductsubarray","number":null,"title":"Maximum Product Subarray","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Product Subarray.py","code":"class Solution:\n    def maxProduct(self, nums: List[int]) -> int:\n        numsLength = len(nums)\n        if numsLength == 0:\n            return 0\n        maxSoFar = nums[0]\n        minSoFar = nums[0]\n        result = maxSoFar\n        for i in range(1, numsLength):\n            tempMax = max(nums[i], maxSoFar * nums[i], minSoFar * nums[i])\n            tempMin = min(nums[i], minSoFar * nums[i], maxSoFar * nums[i])\n            maxSoFar = tempMax\n            minSoFar = tempMin\n            result = max(result, maxSoFar)\n        return result","hash":"73b91f843afc07a9ff171c398dbfdb8b85753e8ecf91802b26acf353d186e356","origins":[{"source":"solutions","path":"Google Interview Questions/Maximum Product Subarray.py"}]},{"language":"python","name":"Maximum Product Subarray.py","code":"class Solution:\n    def maxProduct(self, nums: List[int]) -> int:\n        maxSoFar = minSoFar = result = nums[0]\n        for num in nums[1:]:\n            maxSoFar, minSoFar = max(num, maxSoFar * num, minSoFar * num), min(num, maxSoFar * num, minSoFar * num)\n            result = max(maxSoFar, result)\n        return result","hash":"54dfb3e9634a54269027ba66cc5eae6cc69ea2c74f24ee74bdb31f3e474904c7","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Maximum Product Subarray.py"}]}],"sources":["solutions"]},"topic-maximumprofitofoperatingacentennialwheel":{"key":"topic-maximumprofitofoperatingacentennialwheel","number":null,"title":"Maximum Profit of Operating a Centennial Wheel","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Profit of Operating a Centennial Wheel.py","code":"class Solution:\n    def minOperationsMaxProfit(self, customers: List[int], boardingCost: int, runningCost: int) -> int:\n        remainingCustomers, customersServed, rotation, maxProfit, result, i = 0, 0, 0, -1, 0, 0\n        while remainingCustomers > 0 or i < len(customers):\n            rotation += 1\n            remainingCustomers += customers[i] if i < len(customers) else 0\n            if remainingCustomers < 4:\n                customersServed += remainingCustomers\n                remainingCustomers = 0\n            else:\n                customersServed += 4\n                remainingCustomers -= 4\n            profit = customersServed * boardingCost - rotation * runningCost\n            if maxProfit < profit:\n                maxProfit = profit\n                result = rotation\n            i += 1\n        return -1 if maxProfit <= 0 else result","hash":"3b474f9cd902fcd5821a6e7881baf30d0a36796c64f1bcf425d01ec85590a561","origins":[{"source":"solutions","path":"Weekly Contests/Weekly Contest 208/Maximum Profit of Operating a Centennial Wheel.py"}]}],"sources":["solutions"]},"topic-maximumsumbstinbinarytree":{"key":"topic-maximumsumbstinbinarytree","number":null,"title":"Maximum Sum BST in Binary Tree","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Sum BST in Binary Tree.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def maxSumBST(self, root: Optional[TreeNode]) -> int:\n        self.result = 0\n        def postorder(node: Optional[TreeNode]):\n            if not node:\n                return 0, float('inf'), float('-inf')\n            left_sum, left_min, left_max = postorder(node.left)\n            right_sum, right_min, right_max = postorder(node.right)\n            if left_max < node.val < right_min:\n                total = node.val + left_sum + right_sum\n                self.result = max(total, self.result)\n                return total, min(left_min, node.val), max(right_max, node.val)\n            return 0, float('-inf'), float('inf')\n        postorder(root)\n        return self.result","hash":"561fbaa1ec46b39ebdff1ea32d5d18df1338e257916e2b8eb1ad7e3880593d59","origins":[{"source":"solutions","path":"Maximum Sum BST in Binary Tree.py"}]}],"sources":["solutions"]},"topic-maximumsumcircularsubarray":{"key":"topic-maximumsumcircularsubarray","number":null,"title":"Maximum Sum Circular Subarray","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Sum Circular Subarray.py","code":"class Solution:\n    def maxSubarraySumCircular(self, nums: List[int]) -> int:\n        currMax, currMin, currSum, maxSum, minSum = 0, 0, 0, nums[0], nums[0]\n        for num in nums:\n            currMax = max(currMax, 0) + num\n            maxSum = max(currMax, maxSum)\n            currMin = min(currMin, 0) + num\n            minSum = min(currMin, minSum)\n            currSum += num\n        return maxSum if minSum == currSum else max(maxSum, currSum - minSum)","hash":"195767cbb028b44f263f037b05e161fdd38ae2cd6601e1bbfeff2743ab5a0126","origins":[{"source":"solutions","path":"LeetCoding Challenges/2023/2023-01 Leetcoding Challenge/Maximum Sum Circular Subarray.py"}]}],"sources":["solutions"]},"topic-maximumsumobtainedofanypermutation":{"key":"topic-maximumsumobtainedofanypermutation","number":null,"title":"Maximum Sum Obtained of Any Permutation","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum Sum Obtained of Any Permutation.py","code":"class Solution:\n    def maxSumRangeQuery(self, nums: List[int], requests: List[List[int]]) -> int:\n        count = [0] * len(nums)\n        for start, end in requests:\n            count[start] += 1\n            if end + 1 < len(count):\n                count[end + 1] -= 1\n        currentCount = 0\n        for i in range(len(count)):\n            count[i] += currentCount\n            currentCount = count[i]\n        return sum(num * freq for num, freq in zip(sorted(nums, reverse = True), sorted(count, reverse = True))) % (10 ** 9 + 7)","hash":"3f5fb9fb061645298de85b91403521be547fb2fc47e2dcb650ab7001dd6333ba","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 35/Maximum Sum Obtained of Any Permutation.py"}]}],"sources":["solutions"]},"topic-maximumxorforeachquery":{"key":"topic-maximumxorforeachquery","number":null,"title":"Maximum XOR for Each Query","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum XOR for Each Query.py","code":"class Solution:\n    def getMaximumXor(self, nums: List[int], maximumBit: int) -> List[int]:\n        result, dp = [0] * len(nums), [0] * len(nums)\n        dp[0] = nums[0]\n        for i in range(1, len(nums)):\n            dp[i] = dp[i - 1] ^ nums[i]\n        for i in range(len(nums) - 1, -1, -1):\n            result[len(nums) - 1 - i] = dp[i] ^ (pow(2, maximumBit) - 1)\n        return result","hash":"3bff6d73f017764c97f2c63dce185205fa8f0c66dedf528fd130e96f1a8e4643","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 50/Maximum XOR for Each Query.py"}]}],"sources":["solutions"]},"topic-maximumxoroftwonumbersinanarray":{"key":"topic-maximumxoroftwonumbersinanarray","number":null,"title":"Maximum XOR of Two Numbers in an Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Maximum XOR of Two Numbers in an Array.py","code":"class Solution:\n    def findMaximumXOR(self, nums: List[int]) -> int:\n        L = len(bin(max(nums))) - 2\n        nums = [[(num >> i) & 1 for i in range(L)][::-1] for num in nums]\n        maxXor, trie = 0, {}\n        for num in nums:\n            currentNode, xorNode, currentXor = trie, trie, 0\n            for bit in num:\n                currentNode = currentNode.setdefault(bit, {})\n                toggledBit = 1 - bit\n                if toggledBit in xorNode:\n                    currentXor = (currentXor << 1) | 1\n                    xorNode = xorNode[toggledBit]\n                else:\n                    currentXor = currentXor << 1\n                    xorNode = xorNode[bit]\n            maxXor = max(maxXor, currentXor)\n        return maxXor","hash":"f5ac340487b5cec80f04cae34d71a00c7d847d7203aa2eaa568afe48a95d8d66","origins":[{"source":"solutions","path":"LeetCoding Challenges/2020/2020-09 Leetcoding Challenge/Maximum XOR of Two Numbers in an Array.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-01 LeetCoding Challenge/Maximum XOR of Two Numbers in an Array.py"},{"source":"solutions","path":"Trie/Maximum XOR of Two Numbers in an Array.py"}]}],"sources":["solutions"]},"topic-meanofarrayafterremovingsomeelements":{"key":"topic-meanofarrayafterremovingsomeelements","number":null,"title":"Mean of Array After Removing Some Elements","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Mean of Array After Removing Some Elements.py","code":"class Solution:\n    def trimMean(self, arr: List[int]) -> float:\n        arr.sort()\n        arrLength = len(arr)\n        return sum(arr[int(0.05 * arrLength): int(0.95 * arrLength)]) / int(0.9 * arrLength)","hash":"58755b33f9c8fd865cb6ba95b293a563bd21927e5004e0847cb0c49637a55eb8","origins":[{"source":"solutions","path":"Weekly Contests/Biweekly Contest 37/Mean of Array After Removing Some Elements.py"}]}],"sources":["solutions"]},"topic-meetingroomsiiheap":{"key":"topic-meetingroomsiiheap","number":null,"title":"Meeting Rooms II Heap","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Meeting Rooms II - Heap.py","code":"class Solution:\n    def minMeetingRooms(self, intervals: List[List[int]]) -> int:\n        if not intervals:\n            return 0\n        intervals.sort(key = lambda x : x[0])\n        occupiedRooms = []\n        heappush(occupiedRooms, intervals[0][1])\n        for interval in intervals[1:]:\n            if occupiedRooms[0] <= interval[0]:\n                heappop(occupiedRooms)\n            heappush(occupiedRooms, interval[1])\n        return len(occupiedRooms)","hash":"fbe4370d9ce586276eb59374ab176b802718b20a5b89419d34a6a774051d405c","origins":[{"source":"solutions","path":"Meeting Rooms II - Heap.py"}]}],"sources":["solutions"]},"topic-meetingscheduler":{"key":"topic-meetingscheduler","number":null,"title":"Meeting Scheduler","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Meeting Scheduler.py","code":"class Solution:\n    def minAvailableDuration(self, slots1: List[List[int]], slots2: List[List[int]], duration: int) -> List[int]:\n        timeslots = list(filter(lambda x: x[1] - x[0] >= duration, slots1 + slots2))\n        heapq.heapify(timeslots)\n        while len(timeslots) > 1:\n            start1, end1 = heapq.heappop(timeslots)\n            start2, end2 = timeslots[0]\n            if end1 >= start2 + duration:\n                return [start2, start2 + duration]\n        return []","hash":"1e0f0bd0a19116a5fc4f99976d382b41713f08d7a4793bbe78f743ace37dd230","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-04 Leetcoding Challenge/Meeting Scheduler.py"}]}],"sources":["solutions"]},"topic-mergeksortedlistsdivideandconquer":{"key":"topic-mergeksortedlistsdivideandconquer","number":null,"title":"Merge K Sorted Lists Divide and Conquer","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Merge K Sorted Lists - Divide and Conquer.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nclass Solution:\n    def mergeKLists(self, lists: List[ListNode]) -> ListNode:\n        if len(lists) == 0:\n            return None\n        \n        def mergeTwoLists(l1, l2):\n            head = current = ListNode(0)\n            while l1 and l2:\n                if l1.val <= l2.val:\n                    current.next = l1\n                    l1 = l1.next\n                else:\n                    current.next = l2\n                    l2 = l2.next\n                current = current.next\n            if l1 is None:\n                current.next = l2\n            else:\n                current.next = l1\n            return head.next\n        \n        amount = len(lists)\n        interval = 1\n        while interval < amount:\n            for i in range(0, amount-interval, interval * 2):\n                lists[i] = mergeTwoLists(lists[i], lists[i + interval])\n            interval *= 2\n        return lists[0] if amount > 0 else lists","hash":"21d102a8705bd0133f5669c767d67950aab96a13357a36eea1ef49f51446a7e3","origins":[{"source":"solutions","path":"Google Interview Questions/Merge K Sorted Lists - Divide and Conquer.py"}]}],"sources":["solutions"]},"topic-mergeksortedlistsusingpriorityqueue":{"key":"topic-mergeksortedlistsusingpriorityqueue","number":null,"title":"Merge K Sorted Lists Using Priority Queue","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Merge K Sorted Lists - Using Priority Queue.py","code":"# Definition for singly-linked list.\n# class ListNode:\n#     def __init__(self, val=0, next=None):\n#         self.val = val\n#         self.next = next\nfrom queue import PriorityQueue\n\nclass Solution:\n    def mergeKLists(self, lists: List[ListNode]) -> ListNode:\n        class Wrapper():\n            def __init__(self, node):\n                self.node = node\n            def __lt__(self, other):\n                return self.node.val < other.node.val\n        \n        head = currentNode = ListNode(0)\n        priorityQueue = PriorityQueue()\n        for linkedList in lists:\n            if linkedList:\n                priorityQueue.put(Wrapper(linkedList))\n        while not priorityQueue.empty():\n            node = priorityQueue.get().node\n            currentNode.next = node\n            currentNode = currentNode.next\n            node = node.next\n            if node:\n                priorityQueue.put(Wrapper(node))\n        return head.next","hash":"6073bab0e50a34a4990f0466011c7b96e9cf9127246586e28bb07c6fcffab6df","origins":[{"source":"solutions","path":"Google Interview Questions/Merge K Sorted Lists - Using Priority Queue.py"}]}],"sources":["solutions"]},"topic-mergesimilaritems":{"key":"topic-mergesimilaritems","number":null,"title":"Merge Similar Items","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Merge Similar Items.py","code":"class Solution:\n    def mergeSimilarItems(self, items1: List[List[int]], items2: List[List[int]]) -> List[List[int]]:\n        hashMap = defaultdict(int)\n        for item in items1:\n            hashMap[item[0]] += item[1]\n        for item in items2:\n            hashMap[item[0]] += item[1]\n        return [[key, hashMap[key]] for key in sorted(hashMap.keys())]","hash":"82f3dd908ba55263478bbea7f9079f316073375485b9bdab78e1d0f623e7b1e0","origins":[{"source":"solutions","path":"Merge Similar Items.py"}]}],"sources":["solutions"]},"topic-mergesimilaritemsonelinesolution":{"key":"topic-mergesimilaritemsonelinesolution","number":null,"title":"Merge Similar Items One line solution","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Merge Similar Items - One line solution.py","code":"class Solution:\n    def mergeSimilarItems(self, items1: List[List[int]], items2: List[List[int]]) -> List[List[int]]:\n        return list(sorted((Counter({item[0]: item[1] for item in items1}) + Counter({item[0]: item[1] for item in items2})).items()))","hash":"cab3f60db2d486e5761b7d6261523dff4d7021a6480cd055f2e3270b3012b64e","origins":[{"source":"solutions","path":"Merge Similar Items - One line solution.py"}]}],"sources":["solutions"]},"algorithm-merge-sort":{"key":"algorithm-merge-sort","number":null,"title":"merge sort","difficulty":"Unknown","tags":["Algorithm Reference"],"documents":[],"sources":["algorithms"],"solutions":[{"language":"python","name":"merge_sort.py","code":"\"\"\"\nThe merge sort algorithm.\n\nFor doctests, run the following command:\npython -m doctest -v merge_sort.py\nor\npython3 -m doctest -v merge_sort.py\nFor manual testing, run:\npython merge_sort.py\n\"\"\"\n\nfrom typing import Protocol\n\n\nclass Comparable(Protocol):\n    def __lt__(self, other: object, /) -> bool: ...\n\n\ndef merge_sort[T: Comparable](collection: list[T]) -> list[T]:\n    \"\"\"\n    Sorts a list using the merge sort algorithm.\n\n    :param collection: A collection with comparable items.\n    :return: The collection ordered in ascending order.\n\n    Time Complexity: O(n log n)\n    Space Complexity: O(n)\n\n    Examples:\n    >>> merge_sort([0, 5, 3, 2, 2])\n    [0, 2, 2, 3, 5]\n\n    >>> merge_sort([])\n    []\n\n    >>> merge_sort([-2, -45, -5])\n    [-45, -5, -2]\n    \"\"\"\n\n    def merge(left: list[T], right: list[T]) -> list[T]:\n        \"\"\"\n        Merge two sorted lists into a single sorted list.\n\n        :param left: Left collection\n        :param right: Right collection\n        :return: Merged result\n        \"\"\"\n        result: list[T] = []\n        while left and right:\n            if right[0] < left[0]:\n                result.append(right.pop(0))\n            else:\n                result.append(left.pop(0))\n        result.extend(left)\n        result.extend(right)\n        return result\n\n    if len(collection) <= 1:\n        return collection\n    mid_index = len(collection) // 2\n    return merge(merge_sort(collection[:mid_index]), merge_sort(collection[mid_index:]))\n\n\nif __name__ == \"__main__\":\n    import doctest\n\n    doctest.testmod()\n\n    try:\n        user_input = input(\"Enter numbers separated by a comma:\\n\").strip()\n        unsorted = [int(item) for item in user_input.split(\",\")]\n        sorted_list = merge_sort(unsorted)\n        print(*sorted_list, sep=\",\")\n    except ValueError:\n        print(\"Invalid input. Please enter valid integers separated by commas.\")\n","hash":"9da6c554d660e20a6b77122f5c3742c2a302a46b803e7641a8cd966d12a33210","origins":[{"source":"algorithms","path":"sorts/merge_sort.py","url":"https://github.com/TheAlgorithms/Python/blob/25c712f2692449e91a57748d328ef34fccf25654/sorts/merge_sort.py","commit":"25c712f2692449e91a57748d328ef34fccf25654"}]}]},"topic-mergesortedarray":{"key":"topic-mergesortedarray","number":null,"title":"Merge Sorted Array","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Merge Sorted Array.py","code":"class Solution:\n    def merge(self, nums1: List[int], m: int, nums2: List[int], n: int) -> None:\n        \"\"\"\n        Do not return anything, modify nums1 in-place instead.\n        \"\"\"\n        p1, p2, p = m - 1, n - 1, m + n - 1\n        while p1 >= 0 and p2 >= 0:\n            if nums1[p1] > nums2[p2]:\n                nums1[p] = nums1[p1]\n                p1 -= 1\n            else:\n                nums1[p] = nums2[p2]\n                p2 -= 1\n            p -= 1\n        nums1[:p2 + 1] = nums2[:p2 + 1]","hash":"8bbc5ed8f2374d3720575aa9bccbba5ce5f374337686d030bc7fde1bf8b5abff","origins":[{"source":"solutions","path":"Arrays/Merge Sorted Array.py"}]},{"language":"python","name":"Merge Sorted Array.py","code":"class Solution:\n    def merge(self, nums1: List[int], m: int, nums2: List[int], n: int) -> None:\n        \"\"\"\n        Do not return anything, modify nums1 in-place instead.\n        \"\"\"\n        i, j, k = m - 1, n - 1, m + n - 1\n        while i >= 0 and j >= 0:\n            if nums1[i] >= nums2[j]:\n                nums1[k] = nums1[i]\n                i -= 1\n            else:\n                nums1[k] = nums2[j]\n                j -= 1\n            k -= 1\n        if j >= 0:\n            while k >= 0:\n                nums1[k] = nums2[j]\n                j -= 1\n                k -= 1","hash":"d58b1aaed8261763e2e3dfa8d0c169083a71632a6eb0ac71ef1ad1a32dbd0cce","origins":[{"source":"solutions","path":"LeetCoding Challenges/2021/2021-01 Leetcoding Challenge/Merge Sorted Array.py"},{"source":"solutions","path":"LeetCoding Challenges/2022/2022-06 Leetcoding Challenge/Merge Sorted Array.py"}]}],"sources":["solutions"]},"topic-mergetwobinarytrees":{"key":"topic-mergetwobinarytrees","number":null,"title":"Merge Two Binary Trees","difficulty":"Unknown","tags":[],"documents":[],"solutions":[{"language":"python","name":"Merge Two Binary Trees.py","code":"# Definition for a binary tree node.\n# class TreeNode:\n#     def __init__(self, val=0, left=None, right=None):\n#         self.val = val\n#         self.left = left\n#         self.right = right\nclass Solution:\n    def mergeTrees(self, root1: Optional[TreeNode], root2: Optional[TreeNode]) -> Optional[TreeNode]:\n        if root1 is None:\n            return root2\n        if root2 is None:\n            return root1\n        root1.val += root2.val\n        root1.left = self.mergeTrees(root1.left, root2.left)\n        root1.right = self.mergeTrees(root1.right, root2.right)\n        return root1","hash":"3d31d74b579739f74ee3cf2811c6373bcdc8249baa3eb7d21db4a2ae4f6f377c","origins":[{"source":"solutions","path":"Merge Two Binary Trees.py"}]}],"sources":["solutions"]}});
